/bin/bash -lc "python3 - <<'PY'
from importlib import metadata
for pkg in ('hw-ibmc-bmcgo','openubmc-bingo','conan'):
    d=metadata.distribution(pkg)
    print(f'[{pkg} {d.version}]')
    for key in ('Requires-Python','Summary'):
        vals=d.metadata.get_all(key) or []
        for v in vals: print(f'{key}: {v}')
    print('Requires-Dist:')
    for req in d.requires or []: print(f'  {req}')
PY"

